pub fn score_bin(
    item_size: u32,
    bin_residual: u32,
    bin_capacity: u32,
    step_index: usize,
    total_items: usize,
    open_bins_count: usize,
    mean_residual: f64,
    next_item_size: u32,
    post_residual: u32,
    fitting_bins_count: usize,
) -> f64 {
    // Start with the residual after placing the item
    let mut score = post_residual as f64;

    // Residual ratio relative to the bin capacity
    let residual_ratio = post_residual as f64 / bin_capacity as f64;

    /* --- Basic residual penalties / rewards --- */
    // Too much free space
    if residual_ratio > 0.80 {
        score += 1.5;
    }
    // Too tight
    if residual_ratio < 0.20 {
        score += 2.0;
    }
    // Sweet spot around 0.50
    if residual_ratio > 0.45 && residual_ratio < 0.55 {
        score -= 1.0;
    }
    // Large leftover relative to the current item
    if post_residual > item_size * 2 {
        score += 1.5;
    }

    /* --- Alignment bonuses --- */
    // Prefer cuts that are multiples of 5 or 7
    if bin_residual % 5 == 0 {
        score -= 0.5;
    }
    if bin_residual % 7 == 0 {
        score -= 0.2;
    }

    /* --- Fit count influence --- */
    if fitting_bins_count == 1 {
        score -= 10.0;
    } else if fitting_bins_count > 4 {
        score += 0.5;
    }

    /* --- Lookahead for the next item --- */
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 3.0; // can accommodate the next item
        } else {
            score += 1.5; // dead space that cannot fit next item
        }
    }

    /* --- Mean residual closeness --- */
    let residual_diff = (bin_residual as f64 - mean_residual).abs();
    if residual_diff < 5.0 {
        score -= 0.5;
    } else if residual_diff > 20.0 {
        score += 1.0;
    }

    /* --- Open bin penalty (logarithmic) --- */
    let open_ratio =
        open_bins_count as f64 / ((total_items as f64 / 20.0).max(1.0));
    if open_bins_count > total_items / 20 {
        score += open_ratio * 0.2 * (1.0 + (open_bins_count as f64).ln());
    }

    /* --- Late‑stream penalty --- */
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.90 {
        score += (1.0 - residual_ratio) * 3.0;
    } else if progress > 0.70 {
        score += (1.0 - residual_ratio) * 1.5;
    }

    /* --- New‑bin candidate handling --- */
    if bin_residual == bin_capacity {
        score -= 0.5; // slight reward for opening a new bin
    } else {
        score += 0.2; // small penalty for using an existing bin
    }

    /* --- Miscellaneous fine‑tuning --- */
    if item_size % 10 == 0 {
        score -= 0.3;
    }
    if post_residual == 0 {
        score += 0.2; // small penalty for exact fit (may create future dead space)
    }
    // Penalize if the bin residual is huge compared to the mean residual
    if bin_residual as f64 > mean_residual * 1.5 {
        score += 1.0;
    }

    score
}

